"""Unit tests for tasks_api.models — Tag, TaskStatus, TaskPriority, Task."""

from datetime import datetime, timezone, timedelta

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


# ──────────────────────────────────────────── Tag normalization ───────────────


class TestTagNormalization:
    def test_lowercase_and_strip(self):
        tag = Tag("  Hello  ")
        assert tag.name == "hello"

    def test_valid_chars_letters_digits_hyphen_underscore(self):
        tag = Tag("my-tag_123")
        assert tag.name == "my-tag_123"

    def test_max_length_32_ok(self):
        tag = Tag("a" * 32)
        assert tag.name == "a" * 32

    def test_max_length_33_rejected(self):
        with pytest.raises(ValueError, match="32 characters or fewer"):
            Tag("a" * 33)

    def test_empty_string_rejected(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("")

    def test_whitespace_only_rejected(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("   ")

    def test_non_string_rejected(self):
        with pytest.raises(TypeError, match="must be a string"):
            Tag(123)  # type: ignore[arg-type]

    @pytest.mark.parametrize("bad_name", ["hello world", "tag!", "a@b", "a.b"])
    def test_illegal_char_rejected(self, bad_name: str):
        with pytest.raises(ValueError, match="illegal character"):
            Tag(bad_name)


# ──────────────────────────────────────── TaskStatus / TaskPriority ───────────


class TestTaskStatus:
    def test_pending_value(self):
        assert TaskStatus.PENDING.value == "pending"

    def test_done_value(self):
        assert TaskStatus.DONE.value == "done"

    def test_is_str_enum(self):
        assert isinstance(TaskStatus.PENDING, str)


class TestTaskPriority:
    def test_low_value(self):
        assert TaskPriority.LOW.value == "low"

    def test_medium_value(self):
        assert TaskPriority.MEDIUM.value == "medium"

    def test_high_value(self):
        assert TaskPriority.HIGH.value == "high"

    @pytest.mark.parametrize(
        "priority, expected",
        [
            (TaskPriority.HIGH, 0),
            (TaskPriority.MEDIUM, 1),
            (TaskPriority.LOW, 2),
        ],
    )
    def test_order_key(self, priority: TaskPriority, expected: int):
        assert TaskPriority.order_key(priority) == expected


# ──────────────────────────────────────────── Task.is_overdue ─────────────────


class TestTaskIsOverdue:
    NOW = datetime(2025, 6, 1, tzinfo=timezone.utc)
    PAST = NOW - timedelta(days=1)
    FUTURE = NOW + timedelta(days=1)

    def test_pending_past_due_is_overdue(self):
        task = Task(id=1, title="t", status=TaskStatus.PENDING, due_at=self.PAST)
        assert task.is_overdue(self.NOW) is True

    def test_done_past_due_not_overdue(self):
        task = Task(id=1, title="t", status=TaskStatus.DONE, due_at=self.PAST)
        assert task.is_overdue(self.NOW) is False

    def test_no_due_at_not_overdue(self):
        task = Task(id=1, title="t", status=TaskStatus.PENDING, due_at=None)
        assert task.is_overdue(self.NOW) is False

    def test_pending_future_due_not_overdue(self):
        task = Task(id=1, title="t", status=TaskStatus.PENDING, due_at=self.FUTURE)
        assert task.is_overdue(self.NOW) is False

"""Unit tests for tasks_api.repository — InMemoryTaskRepository, normalize_tags."""

import pytest

from tasks_api.models import Tag, Task, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags


# ──────────────────────────────────── InMemoryTaskRepository lifecycle ────────


class TestInMemoryTaskRepository:
    @pytest.fixture()
    def repo(self):
        return InMemoryTaskRepository()

    def test_next_id_starts_at_1(self, repo):
        assert repo.next_id() == 1

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3

    def test_add_and_get(self, repo):
        task = Task(id=1, title="test")
        repo.add(task)
        assert repo.get(1) is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_list_returns_all(self, repo):
        repo.add(Task(id=1, title="a"))
        repo.add(Task(id=2, title="b"))
        result = list(repo.list())
        assert len(result) == 2

    def test_list_empty(self, repo):
        assert list(repo.list()) == []

    def test_update_existing(self, repo):
        task = Task(id=1, title="old")
        repo.add(task)
        task.title = "new"
        repo.update(task)
        assert repo.get(1).title == "new"

    def test_update_missing_raises_key_error(self, repo):
        with pytest.raises(KeyError):
            repo.update(Task(id=999, title="x"))

    def test_delete_existing(self, repo):
        repo.add(Task(id=1, title="x"))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(999) is False

    def test_add_duplicate_id_raises(self, repo):
        repo.add(Task(id=1, title="first"))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(Task(id=1, title="second"))


# ──────────────────────────────────────── normalize_tags ──────────────────────


class TestNormalizeTags:
    def test_dedup_preserves_first_seen(self):
        result = normalize_tags([Tag("alpha"), Tag("beta"), Tag("alpha")])
        names = [t.name for t in result]
        assert names == ["alpha", "beta"]

    def test_string_to_tag_conversion(self):
        result = normalize_tags(["Hello", "world"])
        assert all(isinstance(t, Tag) for t in result)
        assert [t.name for t in result] == ["hello", "world"]

    def test_mixed_dedup(self):
        result = normalize_tags(["Work", Tag("work")])
        assert len(result) == 1
        assert result[0].name == "work"

    def test_empty_input(self):
        assert normalize_tags([]) == []

    def test_preserves_order(self):
        result = normalize_tags(["c", "a", "b"])
        assert [t.name for t in result] == ["c", "a", "b"]

