        result = normalize_tags([Tag("alpha"), Tag("beta"), Tag("alpha")])
        names = [t.name for t in result]
        assert names == ["alpha", "beta"]

    def test_string_to_tag_conversion(self):
        result = normalize_tags(["Hello", "world"])
        assert all(isinstance(t, Tag) for t in result)
        assert [t.name for t in result] == ["hello", "world"]

    def test_mixed_dedup(self):
        result = normalize_tags(["Work", Tag("work")])
        assert len(result) == 1
        assert result[0].name == "work"

    def test_empty_input(self):
        assert normalize_tags([]) == []

    def test_preserves_order(self):
        result = normalize_tags(["c", "a", "b"])
        assert [t.name for t in result] == ["c", "a", "b"]

